<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import 'element-plus/dist/index.css'
import {api} from './api'
import FinalResultsAdmin from './FinalResultsAdmin.vue'
const route=useRoute(),router=useRouter()
const clone=(value:any)=>JSON.parse(JSON.stringify(value))
const me=ref<any>(null),competitions=ref<any[]>([]),cid=ref(''),tab=ref('dashboard'),busy=ref(false),error=ref(''),details=ref<any>(null),dirty=ref(false)
const teams=ref<any[]>([]),stages=ref<any[]>([]),matches=ref<any[]>([]),announcements=ref<any[]>([]),streams=ref<any[]>([]),batches=ref<any[]>([]),logs=ref<any[]>([])
const login=ref({username:'',password:''}),password=ref({current_password:'',password:''})
const form=ref<any>({}),team=ref<any>(null),stage=ref<any>({name:'',type:'single',config:{best_of:1,groups:4,qualify:2,draw:'manual',random_seed:2026,grand_final_reset:false,third_place:false},entries:[]})
const result=ref<any>(null),selectedMatch=ref<any>(null),impact=ref<any>(null),preview=ref<any>(null),mode=ref('create'),file=ref<File|null>(null),query=ref('')
const article=ref<any>({title:'',body:'',published:false,pinned:false,publish_at:''}),live=ref<any>({room_url:'',replay_url:'',status:'offline',match_id:''})
const manualGroups=ref(''),qualifierOrder=ref('')
const resolution=ref<any>({stage_id:'',group:'A',teams:[],reason:''})
const tabs=[['dashboard','概览'],['competitions','赛事设置'],['roster','参赛名单'],['imports','Excel 导入'],['stages','阶段与分组'],['schedule','赛程发布'],['results','成绩工作台'],['final-results','最终排名与奖励'],['content','公告管理'],['live','直播管理'],['audit-logs','操作日志'],['account','账号设置']]
const current=computed(()=>competitions.value.find(x=>x.id===cid.value))
const filteredTeams=computed(()=>teams.value.filter(t=>t.name.includes(query.value)||t.code.includes(query.value)))
const filteredMatches=computed(()=>matches.value.filter(m=>!resolution.value.stage_id||m.stage_id===resolution.value.stage_id))
const teamName=(id:string)=>teams.value.find(t=>t.id===id)?.name||'待定'
async function action(fn:()=>Promise<any>){busy.value=true;error.value='';details.value=null;try{return await fn()}catch(e:any){error.value=e.message;details.value=e.details;if(e.status===401){me.value=null;router.push('/admin/login')}if(e.status===409)preview.value=null;return null}finally{busy.value=false}}
async function refresh(){
 competitions.value=await api('/admin/competitions')
 if(!cid.value&&competitions.value.length)cid.value=competitions.value[0].id
 if(cid.value){
  const prefix='/admin/competitions/'+cid.value
  ;[teams.value,stages.value,matches.value,announcements.value,streams.value,batches.value]=await Promise.all(['/registrations','/stages','/matches','/announcements','/live','/imports'].map(x=>api(prefix+x)))
 }
 if(current.value)form.value={...current.value,map_pool_text:current.value.map_pool.join(', ')}
 logs.value=await api('/admin/audit-logs')
}
async function boot(){await action(async()=>{me.value=await api('/admin/auth/me');if(route.path.startsWith('/admin/matches/')){const m=await api('/admin/matches/'+route.path.split('/')[3]);cid.value=m.competition_id;tab.value='results';await refresh();openResult(m)}else await refresh()})}
async function signIn(){await action(async()=>{const user=await api('/admin/auth/login','POST',login.value);login.value.password='';await refresh();await router.push('/admin/competitions');me.value=user})}
function navigate(value:string){if(dirty.value&&!window.confirm('有未保存修改，确定离开？'))return;dirty.value=false;tab.value=value;router.push(cid.value?'/admin/competitions/'+cid.value+'/'+value:'/admin/'+value)}
async function selectCompetition(){preview.value=null;team.value=null;result.value=null;impact.value=null;dirty.value=false;await action(refresh);navigate(tab.value)}
function newCompetition(){form.value={name:'',slug:'',season:'',organizer:'学生社团赛事',description:'',rules:'',map_pool_text:'',team_limit:32,status:'draft',is_default:false}}
async function saveCompetition(){await action(async()=>{let f={...form.value,map_pool:form.value.map_pool_text.split(',').map((s:string)=>s.trim()).filter(Boolean)};let saved=await api('/admin/competitions'+(f.id?'/'+f.id:''),f.id?'PATCH':'POST',f);cid.value=saved.id;dirty.value=false;await refresh();ElMessage.success('赛事已保存')})}
function newTeam(){team.value={code:'',name:'',contact:'',description:'',logo:'',members:Array.from({length:5},(_,i)=>({nickname:'',steam_id:'',role:'正式',captain:i===0}))}}
async function saveTeam(){await action(async()=>{const t=team.value;if(t.revision_reason){await api('/admin/registrations/'+t.id+'/roster-revisions','POST',{...t,expected_version:t.version,reason:t.revision_reason});team.value=null;dirty.value=false;await refresh();return}await api(t.id?'/admin/registrations/'+t.id:'/admin/competitions/'+cid.value+'/registrations',t.id?'PATCH':'POST',t);team.value=null;dirty.value=false;await refresh();ElMessage.success('名单已保存')})}
async function uploadLogo(event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(!f)return;await action(async()=>{const body=new FormData();body.append('file',f);const r=await api('/admin/assets','POST',body);team.value.logo=r.url})}
async function previewImport(){if(!file.value)return;await action(async()=>{const body=new FormData();body.append('file',file.value!);body.append('mode',mode.value);preview.value=await api('/admin/competitions/'+cid.value+'/imports/preview','POST',body)})}
async function commitImport(){await action(async()=>{const r=await api('/admin/imports/'+preview.value.id+'/commit','POST',{idempotency_key:preview.value.id});preview.value=r;dirty.value=false;await refresh();ElMessage.success('整批导入成功')})}
async function saveStage(){await action(async()=>{const s=stage.value;s.competition_id=cid.value;if(manualGroups.value.trim())s.config.manual_groups=manualGroups.value.trim().split('\n').map(line=>line.split(',').map(code=>{const t=teams.value.find(t=>t.code===code.trim());if(!t)throw new Error('未知队伍编号：'+code);return t.id}));if(qualifierOrder.value.trim())s.config.qualifier_order=qualifierOrder.value.split(',').map(x=>'group:'+x.trim().replace(/([A-Z])(\d+)/,'$1:$2'));const saved=await api('/admin/stages'+(s.id?'/'+s.id:''),s.id?'PATCH':'POST',s);await api('/admin/stages/'+saved.id+'/entries','PUT',{entries:s.entries});stage.value={...s,id:saved.id};dirty.value=false;await refresh();ElMessage.success('阶段与种子已保存')})}
async function generate(s:any){await action(async()=>{await api('/admin/stages/'+s.id+'/generate','POST',{idempotency_key:s.id});await refresh();tab.value='schedule';ElMessage.success('草稿已生成，尚未发布')})}
async function publish(s:any){await action(async()=>{await api('/admin/schedule-generations/'+s.id+'/publish','POST',{});await refresh();ElMessage.success('赛程已发布')})}
function openResult(m:any){selectedMatch.value=m;result.value={...(m.confirmed?m.result:m.draft_result),expected_version:m.version,maps:clone((m.confirmed?m.result:m.draft_result).maps||[]),reason:'',result_type:(m.confirmed?m.result:m.draft_result).result_type||'normal'};impact.value=null}
async function saveResult(){await action(async()=>{const m=await api('/admin/matches/'+selectedMatch.value.id+'/result','PUT',result.value);dirty.value=false;await refresh();openResult(m);ElMessage.success('草稿已保存')})}
async function confirmResult(){await action(async()=>{const m=await api('/admin/matches/'+selectedMatch.value.id+'/result/confirm','POST',{expected_version:selectedMatch.value.version});dirty.value=false;await refresh();openResult(m);ElMessage.success('成绩正式确认')})}
async function revisePreview(){await action(async()=>{impact.value=await api('/admin/matches/'+selectedMatch.value.id+'/result/revise-preview','POST',result.value)})}
async function revise(){await action(async()=>{const m=await api('/admin/matches/'+selectedMatch.value.id+'/result/revise','POST',result.value);dirty.value=false;await refresh();openResult(m);ElMessage.success('修正已保存')})}
async function arrange(m:any){await action(async()=>{await api('/admin/matches/'+m.id,'PATCH',{scheduled_at:m.scheduled_at,status:m.status});await refresh()})}
async function saveArticle(){await action(async()=>{await api('/admin/announcements'+(article.value.id?'/'+article.value.id:''),article.value.id?'PATCH':'POST',{...article.value,competition_id:cid.value});article.value={title:'',body:'',published:false,pinned:false,publish_at:''};dirty.value=false;await refresh()})}
async function saveLive(){await action(async()=>{await api('/admin/live-streams'+(live.value.id?'/'+live.value.id:''),live.value.id?'PATCH':'POST',{...live.value,competition_id:cid.value});await refresh();dirty.value=false})}
watch(()=>route.path,()=>{const parts=route.path.split('/');if(parts[2]==='competitions'&&parts[3])cid.value=parts[3];const last=parts.at(-1)||'competitions';if(tabs.some(t=>t[0]===last))tab.value=last},{immediate:true})
onBeforeRouteLeave(()=>!dirty.value||window.confirm('有未保存修改，确定离开？'))
if(route.path!='/admin/login')boot()
</script>
<template>

<div class="admin-app">
<header><RouterLink to="/">广金主场 ↗</RouterLink><b>唯一管理员工作台</b><el-button v-if="me" @click="action(async()=>{await api('/admin/auth/logout','POST',{});me=null;router.push('/admin/login')})">退出</el-button></header>
<el-alert v-if="error" :title="error" type="error" :closable="false" show-icon /><pre v-if="details" class="error-details">{{JSON.stringify(details,null,2)}}</pre>
<el-card v-if="!me" class="login"><h1>管理员登录</h1><el-form label-position="top" @submit.prevent="signIn"><el-form-item label="账号"><el-input v-model="login.username" autocomplete="username" /></el-form-item><el-form-item label="密码"><el-input v-model="login.password" type="password" show-password autocomplete="current-password" /></el-form-item><el-button native-type="submit" type="primary" :loading="busy">登录</el-button></el-form></el-card>
<template v-else><div class="toolbar"><label>当前赛事</label><el-select v-model="cid" @change="selectCompetition"><el-option v-for="c in competitions" :label="c.name" :value="c.id" /></el-select><span>{{current?.status}}</span><RouterLink v-if="current?.published" :to="'/competitions/'+current.slug">查看公开页面 ↗</RouterLink></div><nav><el-button v-for="t in tabs" :disabled="busy" :type="tab===t[0]?'primary':'default'" @click="navigate(t[0])">{{t[1]}}</el-button></nav>
<main v-loading="busy" @input="dirty=true">
<section v-if="tab==='dashboard'"><h1>当前赛事概览</h1><div class="form-grid"><el-card>参赛队伍：{{teams.length}}</el-card><el-card>比赛总数：{{matches.length}}</el-card><el-card>待安排：{{matches.filter(m=>m.status==='unscheduled').length}}</el-card><el-card>进行中：{{matches.filter(m=>m.status==='ongoing').length}}</el-card></div><h2>近期导入</h2><p v-for="b in batches.slice(0,5)">{{b.filename}} · {{b.status}} · {{b.created_at}}</p></section><section v-else-if="tab==='competitions'"><div class="toolbar"><h1>赛事设置</h1><el-button @click="newCompetition">新建赛事</el-button></div><el-form label-position="top"><div class="form-grid"><el-form-item label="赛事名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="稳定路径（英文、数字、横线）"><el-input v-model="form.slug" :disabled="!!form.id" /></el-form-item><el-form-item label="赛季"><el-input v-model="form.season" /></el-form-item><el-form-item label="组织方"><el-input v-model="form.organizer" /></el-form-item><el-form-item label="队伍上限"><el-input-number v-model="form.team_limit" :min="2" :max="32" /></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option v-for="s in ['draft','roster_preparation','scheduling','ongoing','completed','archived']" :value="s" :label="s" /></el-select></el-form-item></div><el-form-item label="简介"><el-input v-model="form.description" type="textarea" /></el-form-item><el-form-item label="正式赛事规则（包括同分、加时和晋级规则）"><el-input v-model="form.rules" type="textarea" :rows="8" /></el-form-item><el-form-item label="地图池（英文逗号分隔）"><el-input v-model="form.map_pool_text" /></el-form-item><el-form-item label="首页焦点比赛"><el-select v-model="form.focus_match_id" clearable><el-option v-for="m in matches" :value="m.id" :label="m.code+' '+teamName(m.a)+' vs '+teamName(m.b)" /></el-select></el-form-item><el-checkbox v-model="form.is_default">设为首页默认赛事</el-checkbox><div class="toolbar"><el-button type="primary" @click="saveCompetition">保存赛事</el-button><el-button v-if="form.id" @click="action(async()=>{await api('/admin/competitions/'+cid+'/publish','POST',{});await refresh()})">发布赛事</el-button><el-button v-if="form.id" @click="action(async()=>{await api('/admin/competitions/'+cid+'/archive','POST',{});await refresh()})">归档赛事</el-button></div></el-form></section>
<section v-else-if="!cid&&tab!=='account'&&tab!=='audit-logs'"><el-empty description="请先创建赛事" /></section>
<section v-else-if="tab==='roster'"><div class="toolbar"><h1>参赛名单</h1><el-input v-model="query" placeholder="搜索队名或编号" style="max-width:240px"/><el-button @click="newTeam">手工录入整队</el-button></div><el-table :data="filteredTeams"><el-table-column prop="code" label="编号"/><el-table-column prop="name" label="队名"/><el-table-column prop="contact" label="联系方式（私密）"/><el-table-column label="名单版本"><template #default="s">v{{s.row.version}}</template></el-table-column><el-table-column label="操作" width="190"><template #default="s"><el-button @click="team=clone(s.row)">编辑</el-button><el-button type="danger" @click="action(async()=>{await ElMessageBox.confirm('确认撤销该队资格？');await api('/admin/registrations/'+s.row.id+'/withdraw','POST',{});await refresh()})">撤销</el-button></template></el-table-column></el-table>
<el-dialog :model-value="!!team" @update:model-value="team=null" title="整队名单（五名正式，最多两名替补）" width="min(1000px,96vw)"><el-form v-if="team" label-position="top"><div class="form-grid"><el-form-item label="稳定队伍编号"><el-input v-model="team.code" :disabled="!!team.id"/></el-form-item><el-form-item label="英文队名"><el-input v-model="team.english_name" maxlength="120"/></el-form-item><el-form-item label="徽章缩写"><el-input v-model="team.emblem_text" maxlength="12"/></el-form-item><el-form-item label="海报标题第一行"><el-input :model-value="team.poster_title_lines?.[0]" @update:model-value="(v:string)=>team.poster_title_lines=[v,team.poster_title_lines?.[1]||'']"/></el-form-item><el-form-item label="海报标题第二行"><el-input :model-value="team.poster_title_lines?.[1]" @update:model-value="(v:string)=>team.poster_title_lines=[team.poster_title_lines?.[0]||'',v]"/></el-form-item><el-form-item label="队名"><el-input v-model="team.name"/></el-form-item><el-form-item label="联系方式（不公开）"><el-input v-model="team.contact"/></el-form-item><el-form-item label="简介"><el-input v-model="team.description"/></el-form-item></div><label>队标 PNG/JPEG/WebP（2MiB以内）<input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadLogo"></label><img v-if="team.logo" :src="team.logo" width="48" alt="队标预览"><div v-for="(m,i) in team.members" class="member-row"><el-input v-model="m.nickname" placeholder="游戏昵称"/><el-input v-model="m.steam_id" placeholder="SteamID64 原始文本"/><el-select v-model="m.role"><el-option label="正式" value="正式"/><el-option label="替补" value="替补"/></el-select><el-checkbox v-model="m.captain">队长</el-checkbox><el-button @click="team.members.splice(i,1)">移除</el-button></div><el-button :disabled="team.members.length>=7" @click="team.members.push({nickname:'',steam_id:'',role:'替补',captain:false})">增加替补</el-button><el-form-item v-if="team.id" label="已锁名单专用变更原因（既有比赛保持快照）"><el-input v-model="team.revision_reason"/></el-form-item><el-button type="primary" @click="saveTeam">保存完整名单</el-button></el-form></el-dialog></section>
<section v-else-if="tab==='imports'"><h1>Excel 名单导入</h1><p>模板 v1 · .xlsx · 5MiB · 最多32队/224人；Steam ID 必须原始文本。</p><a href="/api/v1/admin/imports/template">下载双工作表模板</a><div class="toolbar"><el-radio-group v-model="mode" @change="preview=null"><el-radio value="create">新增</el-radio><el-radio value="update">显式更新</el-radio></el-radio-group><input type="file" accept=".xlsx" @change="file=($event.target as HTMLInputElement).files?.[0]||null;preview=null"><el-button @click="previewImport">上传并预览</el-button></div><template v-if="preview"><el-alert :title="preview.status==='committed'?'整批已导入':'当前仅预览，尚未导入'" :type="preview.status==='committed'?'success':'info'" :closable="false"/><p>{{preview.filename}} · {{preview.payload.team_count}} 队 / {{preview.payload.member_count}} 人 · 新增 {{preview.payload.summary?.new||0}} / 修改 {{preview.payload.summary?.modified||0}} / 未变 {{preview.payload.summary?.unchanged||0}}</p><el-table :data="preview.payload.errors"><el-table-column prop="sheet" label="工作表"/><el-table-column prop="row" label="行号"/><el-table-column prop="column" label="列"/><el-table-column prop="team_code" label="队伍"/><el-table-column prop="message" label="错误原因"/></el-table><details v-for="diff in preview.payload.differences"><summary>{{diff.code}} · {{diff.before?'修改（完整替换成员）':'新增'}}</summary><p v-if="diff.removed_members?.length">将移除：{{diff.removed_members.map((m:any)=>m.nickname).join('、')}}</p><div class="form-grid"><pre>{{JSON.stringify(diff.before,null,2)}}</pre><pre>{{JSON.stringify(diff.after,null,2)}}</pre></div></details><el-button type="primary" :disabled="busy||preview.status==='committed'||preview.payload.errors.length>0" @click="commitImport">确认整批导入</el-button></template><h2>导入历史</h2><el-table :data="batches"><el-table-column prop="filename" label="文件"/><el-table-column prop="mode" label="模式"/><el-table-column prop="created_at" label="时间"/><el-table-column prop="status" label="状态"/><el-table-column label="查看"><template #default="s"><el-button @click="preview=s.row">批次详情</el-button></template></el-table-column></el-table></section>
<section v-else-if="tab==='stages'"><h1>阶段、种子与分组</h1><el-form label-position="top"><div class="form-grid"><el-form-item label="阶段名称"><el-input v-model="stage.name"/></el-form-item><el-form-item label="赛制模板"><el-select v-model="stage.type"><el-option label="单败" value="single"/><el-option label="小组循环＋单败" value="group_single"/><el-option label="标准双败" value="double"/></el-select></el-form-item><el-form-item label="BO"><el-select v-model="stage.config.best_of"><el-option v-for="n in [1,3,5]" :value="n" :label="'BO'+n"/></el-select></el-form-item><el-form-item label="抽签方式"><el-select v-model="stage.config.draw"><el-option label="手动种子顺序" value="manual"/><el-option label="记录种子的随机抽签" value="random"/></el-select></el-form-item><el-form-item label="抽签种子"><el-input-number v-model="stage.config.random_seed"/></el-form-item><el-form-item label="小组数"><el-input-number v-model="stage.config.groups" :min="1" :max="16"/></el-form-item><el-form-item label="每组晋级数"><el-input-number v-model="stage.config.qualify" :min="1" :max="16"/></el-form-item></div><el-checkbox v-model="stage.config.double_round">双循环</el-checkbox><el-checkbox v-model="stage.config.third_place">季军赛</el-checkbox><el-checkbox v-model="stage.config.grand_final_reset">双败总决赛重置</el-checkbox><el-form-item v-if="stage.type==='group_single'" label="手动或混合分组（可选；每行一组，按队伍编号用英文逗号分隔；留空按种子分配）"><el-input v-model="manualGroups" type="textarea" :rows="4" placeholder="T001,T004,T005,T008"/></el-form-item><el-form-item v-if="stage.type==='group_single'" label="跨组种子顺序（可选；例如 A1,B2,B1,A2；完整填写所有晋级位）"><el-input v-model="qualifierOrder"/></el-form-item><el-form-item label="按种子顺序选择参赛队伍"><el-select v-model="stage.entries" multiple filterable style="width:100%"><el-option v-for="t in teams" :label="t.code+' '+t.name" :value="t.id"/></el-select></el-form-item><p>种子顺序：{{stage.entries.map(teamName).join(' → ')}}</p><el-button type="primary" @click="saveStage">保存阶段与种子</el-button></el-form><el-table :data="stages"><el-table-column prop="name" label="阶段"/><el-table-column prop="type" label="模板"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><el-button v-if="s.row.status==='draft'" @click="stage=clone(s.row)">编辑</el-button><el-button v-if="s.row.status==='draft'" @click="generate(s.row)">生成草稿</el-button><el-button v-if="s.row.status==='published'&&s.row.type==='group_single'" @click="action(async()=>{await api('/admin/stages/'+s.row.id+'/qualifications/confirm','POST',{});await refresh()})">确认小组晋级</el-button></template></el-table-column></el-table><h2>有理由的排名裁定</h2><el-select v-model="resolution.stage_id" placeholder="阶段"><el-option v-for="s in stages" :label="s.name" :value="s.id"/></el-select><el-input v-model="resolution.group" placeholder="组别（A/B…）"/><el-select v-model="resolution.teams" multiple placeholder="按最终排名依次选择该组全部队伍"><el-option v-for="t in teams" :label="t.name" :value="t.id"/></el-select><el-input v-model="resolution.reason" placeholder="裁定原因"/><el-button @click="action(async()=>{await api('/admin/stages/'+resolution.stage_id+'/ranking-resolution','PUT',resolution);await refresh()})">提交裁定</el-button></section>
<section v-else-if="tab==='schedule'"><h1>赛程预览与发布</h1><p>生成与时间安排分离。预览不公开；发布后不能重新生成。</p><div v-for="s in stages" class="toolbar"><b>{{s.name}} · {{s.status}}</b><el-button v-if="s.status==='preview'" @click="publish(s)">正式发布</el-button><el-button v-if="s.status==='preview'" type="danger" @click="action(async()=>{await ElMessageBox.confirm('作废这份未发布草稿？');await api('/admin/stages/'+s.id+'/discard','POST',{});await refresh()})">作废草稿</el-button></div><el-table :data="matches"><el-table-column prop="code" label="场次"/><el-table-column label="双方 / 来源" min-width="240"><template #default="s">{{s.row.a?teamName(s.row.a):s.row.source_a}} / {{s.row.b?teamName(s.row.b):s.row.source_b}}</template></el-table-column><el-table-column label="北京时间" width="240"><template #default="s"><el-date-picker v-model="s.row.scheduled_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss+08:00" placeholder="安排时间"/></template></el-table-column><el-table-column label="状态" width="160"><template #default="s"><el-select v-model="s.row.status" :disabled="s.row.confirmed"><el-option v-for="v in ['unscheduled','scheduled','ongoing','postponed','cancelled']" :label="v" :value="v"/></el-select></template></el-table-column><el-table-column label="保存"><template #default="s"><el-button @click="arrange(s.row)">保存安排</el-button></template></el-table-column></el-table></section>
<section v-else-if="tab==='results'"><h1>成绩工作台</h1><el-select placeholder="选择比赛" @change="(id:string)=>openResult(matches.find(m=>m.id===id))" style="width:100%"><el-option v-for="m in matches" :value="m.id" :label="m.code+' '+teamName(m.a)+' vs '+teamName(m.b)+(m.confirmed?'（已确认）':'')"/></el-select><template v-if="result"><h2>{{teamName(selectedMatch.a)}} vs {{teamName(selectedMatch.b)}} · BO{{selectedMatch.best_of}}</h2><p>地图池：{{current?.map_pool.join(' / ')}} · 版本 {{selectedMatch.version}}</p><el-radio-group v-model="result.result_type" @change="result.maps=[]"><el-radio value="normal">正常完赛</el-radio><el-radio value="forfeit">弃权</el-radio><el-radio value="technical">技术判负</el-radio></el-radio-group><template v-if="result.result_type==='normal'"><div v-for="(map,i) in result.maps" class="member-row"><el-select v-model="map.map_name" placeholder="地图"><el-option v-for="n in current?.map_pool" :value="n" :label="n"/></el-select><el-input-number v-model="map.score_a" :min="0"/><span>:</span><el-input-number v-model="map.score_b" :min="0"/><el-checkbox v-model="map.overtime">加时</el-checkbox><el-button @click="result.maps.splice(i,1)">移除</el-button></div><el-button :disabled="result.maps.length>=selectedMatch.best_of" @click="result.maps.push({map_name:'',score_a:0,score_b:0,overtime:false})">添加地图</el-button></template><el-select v-else v-model="result.winner" placeholder="异常胜者"><el-option v-for="id in [selectedMatch.a,selectedMatch.b]" :value="id" :label="teamName(id)"/></el-select><el-input v-model="result.reason" type="textarea" placeholder="异常结果或修正原因（公开，请勿填写私密信息）"/><div class="toolbar"><template v-if="!selectedMatch.confirmed"><el-button @click="saveResult">保存成绩草稿</el-button><el-button type="primary" @click="confirmResult">正式确认已保存草稿</el-button></template><template v-else><el-button @click="revisePreview">预览修正影响</el-button><el-button type="danger" :disabled="!impact||impact.blocking.length>0" @click="revise">提交有理由修正</el-button></template></div><div v-if="impact"><p>影响 {{impact.affected.length}} 场比赛</p><p v-for="m in impact.affected">{{m.code}} · {{m.status}} <RouterLink v-if="impact.blocking.includes(m.id)" :to="'/admin/matches/'+m.id+'/result'">阻塞比赛 ↗</RouterLink></p></div></template></section>
<FinalResultsAdmin v-else-if="tab==='final-results'&&cid" :competition-id="cid" :teams="teams" :stages="stages" :matches="matches"/>
<section v-else-if="tab==='content'"><h1>公告管理</h1><el-form label-position="top"><el-form-item label="标题"><el-input v-model="article.title"/></el-form-item><el-form-item label="正文（纯文本）"><el-input v-model="article.body" type="textarea" :rows="8"/></el-form-item><el-form-item label="计划发布时间（北京时间）"><el-date-picker v-model="article.publish_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss+08:00"/></el-form-item><el-checkbox v-model="article.published">发布</el-checkbox><el-checkbox v-model="article.pinned">置顶</el-checkbox><el-button type="primary" @click="saveArticle">保存公告</el-button></el-form><el-table :data="announcements"><el-table-column prop="title" label="标题"/><el-table-column prop="published" label="已发布"/><el-table-column prop="publish_at" label="计划时间"/><el-table-column label="编辑"><template #default="s"><el-button @click="article=clone(s.row)">编辑 / 下架</el-button></template></el-table-column></el-table></section>
<section v-else-if="tab==='live'"><h1>直播与回放管理</h1><el-form label-position="top"><el-form-item label="B站直播间 HTTPS 链接"><el-input v-model="live.room_url"/></el-form-item><el-form-item label="B站回放 HTTPS 链接"><el-input v-model="live.replay_url"/></el-form-item><el-form-item label="直播状态（人工维护）"><el-select v-model="live.status"><el-option label="未开播" value="offline"/><el-option label="直播中" value="live"/><el-option label="回放" value="replay"/></el-select></el-form-item><el-form-item label="绑定比赛"><el-select v-model="live.match_id" clearable><el-option v-for="m in matches" :label="m.code" :value="m.id"/></el-select></el-form-item><el-button type="primary" @click="saveLive">保存直播配置</el-button></el-form><div v-for="l in streams" class="toolbar"><span>{{l.room_url}} · {{l.status}}</span><el-button @click="live=clone(l)">编辑</el-button></div></section>
<section v-else-if="tab==='audit-logs'"><h1>操作日志（仅管理员）</h1><el-input v-model="query" placeholder="按动作搜索"/><el-table :data="logs.filter(l=>l.action.includes(query))"><el-table-column prop="created_at" label="时间"/><el-table-column prop="action" label="动作"/><el-table-column prop="entity_id" label="对象"/><el-table-column label="变更详情"><template #default="s"><details><summary>查看</summary><pre>{{JSON.stringify(s.row.payload,null,2)}}</pre></details></template></el-table-column></el-table></section>
<section v-else-if="tab==='account'"><h1>修改管理员密码</h1><el-form label-position="top"><el-form-item label="当前密码"><el-input v-model="password.current_password" type="password" autocomplete="current-password"/></el-form-item><el-form-item label="新密码（至少12位）"><el-input v-model="password.password" type="password" autocomplete="new-password"/></el-form-item><el-button type="primary" @click="action(async()=>{await api('/admin/auth/password','PUT',password);me=null;password={current_password:'',password:''};router.push('/admin/login')})">修改并使旧会话失效</el-button></el-form></section>
</main></template>
</div>
</template>
<style>
.admin-app{font-family:'Segoe UI','Microsoft YaHei',sans-serif;color:#202427;background:#f4f5f7;min-height:100vh;color-scheme:light;--el-color-primary:#b52432}.admin-app *{box-sizing:border-box}.admin-app header{padding:20px 28px;display:flex;gap:24px;align-items:center;background:white;border-top:4px solid #b52432}.admin-app header>a{font-size:24px;color:#b52432;text-decoration:none;font-weight:800}.admin-app header .el-button{margin-left:auto}.admin-app>.toolbar,.admin-app>nav,.admin-app>main{margin:20px 28px}.admin-app>main{background:white;padding:28px}.admin-app nav{display:flex;gap:8px;flex-wrap:wrap}.admin-app nav .el-button{margin:0}.admin-app .toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:14px;margin-bottom:20px}.admin-app .toolbar .el-select{width:260px}.admin-app .form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.admin-app .member-row{display:flex;align-items:center;gap:10px;margin:12px 0}.admin-app .member-row>.el-input{min-width:100px}.admin-app .member-row>.el-select{min-width:90px}.admin-app .login{max-width:440px;margin:80px auto;padding:20px}.admin-app pre{white-space:pre-wrap;word-break:break-all;max-height:500px;overflow:auto}.admin-app .error-details{padding:12px 28px;color:#9b1724}.admin-app h1{font-size:24px;margin:0 0 24px}.admin-app h2{font-size:19px;margin-top:30px}.admin-app a{color:#b52432}.admin-app .el-form-item{margin-bottom:18px}@media(max-width:760px){.admin-app .form-grid{grid-template-columns:1fr}.admin-app>.toolbar,.admin-app>nav,.admin-app>main{margin:16px}.admin-app>main{padding:16px}.admin-app .member-row{flex-wrap:wrap}.admin-app header{padding:16px;flex-wrap:wrap}.admin-app .login{margin:30px 16px}}
</style>
